-- Add the new columns (safe if already present) and load Offseason Rankings 1.
alter table public.weeks add column if not exists label text;
alter table public.weeks add column if not exists hero_image_url text;

on conflict (season, week_number) do update set display_date = excluded.display_date, label = excluded.label, status = excluded.status, published_at = excluded.published_at, worst_name = excluded.worst_name, worst_take = excluded.worst_take, dropped_out = excluded.dropped_out, archive_note = excluded.archive_note;

delete from public.rankings where week_id = (select id from public.weeks where season = 2026 and week_number = 1);

