insert into public.rankings (week_id, rank, qb_slug, name, team_code, take, movement) values ((select id from public.weeks where season = 2026 and week_number = 1), 5, 'trevor-lawrence', 'Trevor Lawrence', 'JAX', 'Including the Clemson years, feels like I’ve spent almost a decade calling him a bust. I''m not apologizing, but I am putting him at 5.', '{"kind":"up","delta":2}'::jsonb);
